/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  var channel_type = api.context.props.channelType;
  var msg = '';

  if(channel_type == 'teams') 
    msg = 'Microsoft Teams';
  else if (channel_type == 'slack')
    msg = 'Slack';
  else if (channel_type == 'workplace')
    msg = 'Workplace';

	return 'You’ve successfully integrated '+ msg + ' with the ServiceNow Virtual Agent.';
}

